import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {


  const sumaDeImportes = input.suma_de_importes;
  const iva = parseFloat(input.percentage_pricing.percentage_rate);
  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;  

  console.log(billingItemCode)

  if (!billingItemCode) {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "parameter_billingItem_code for rule Alumbrado publico-Precio por rangos de consumo not found"
      }
    }
  }

     const billingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
    const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);



  if (iva == 0) {
    billingItem.billing_item_amount = 0;
    return {
      ...input,
      result: {
        total_amount: 0,
        status_description: "IVA paramter is zero",
        status: "WARNING"
      }
    };
  } else if (sumaDeImportes == 0) {
    billingItem.billing_item_amount = 0;
    return {
      ...input,
      result: {
        total_amount: 0,
        status_description: "not exist concepts amount",
        status: "ERROR"
      }
    };
  } else {
    const total_amount = sumaDeImportes * (iva/100)
    billingItem.billing_item_amount = total_amount;
    return {
      ...input,
      result: {
        total_amount: total_amount,
        status_description: "IVA amount calculation rule completed",
        status: "OK"
      }
    };
  }
};

import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  // Lista de códigos válidos
  const validCodes =
    input?.parametros_de_la_regla?.valid_concept_codes_for_sum_of_amounts ?? [];


  // Items de energía activa
  const items =
    input?.tsl_wo_work_order_attribute?.billing_items?.active_energy_billing_items ?? [];




  // Acumulador
  let totalAmount = 0;

  // suma de los importes de los codigos de los conceptos validos
  validCodes.forEach(code => {
    // Buscar todos los items con ese código (por si se repite)
    const matchedItems = items.filter(item => item?.legacy_billing_item_id === code);

    // Sumar los amounts de esos items
    const sumForCode = matchedItems.reduce(
      (acc, item) => acc + Number(item?.billing_item_amount ?? 0),
      0
    );

    // Acumular al total general
    totalAmount += sumForCode;

  });


  return {
    ...input,
    suma_de_importes : totalAmount
  }
};
